#!/usr/local/bin/python3
"""os-logwatch ingest, retention, and SMTP alerting daemon."""

from datetime import datetime
import json
import os
import queue
import re
import signal
import socket
import sys
import threading
import time

SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))
if SCRIPT_DIR not in sys.path:
    sys.path.insert(0, SCRIPT_DIR)

import logwatch_core as core

SOCKET_BUF_BYTES = 4 * 1024 * 1024
DGRAM_MAX_BYTES = 65535
FLUSH_BATCH_SIZE = 100
FLUSH_INTERVAL_SEC = 0.25
TICKER_INTERVAL_SEC = 60

# Suppress self-referential configd audit chatter generated by 3s Log Viewer / widget polling
RE_SELF_POLL = re.compile(
    r"(Querying Logwatch database|Fetching Logwatch filter options|Fetching Logwatch dashboard statistics|"
    r"Fetching Logwatch alert cooldown state|Checking Logwatch status|"
    r"action allowed logwatch\.(query|filters|stats|alert-state|status))"
)


class LogwatchDaemon:
    """Ingests syslog-ng JSON datagrams into SQLite WAL and evaluates alerts."""

    def __init__(self):
        self._stop = threading.Event()
        self._reload_flag = threading.Event()
        self._cfg_lock = threading.RLock()
        self._cfg = core.load_config()
        self._conn = core.open_db(core.DB_PATH)
        self._ingest_q = queue.Queue(maxsize=20000)
        self._sock = None
        self._next_digest_flush = 0
        self._digest_window_sec = 0

    def _log(self, level, msg):
        ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        print(f"{ts} [{level}] {msg}", flush=True)

    def _handle_sigterm(self, _signum, _frame):
        self._stop.set()

    def _handle_sighup(self, _signum, _frame):
        self._reload_flag.set()

    def _maybe_reload(self):
        if not self._reload_flag.is_set():
            return
        self._reload_flag.clear()
        try:
            new_cfg = core.load_config()
            with self._cfg_lock:
                self._cfg = new_cfg
            self._log("info", "Reloaded os-logwatch configuration and rules")
        except Exception as exc:
            self._log("error", f"Failed to reload configuration: {exc}")

    def _bind_socket(self):
        os.makedirs(core.RUN_DIR, mode=0o755, exist_ok=True)
        if os.path.exists(core.INGEST_SOCK):
            os.unlink(core.INGEST_SOCK)

        sock = socket.socket(socket.AF_UNIX, socket.SOCK_DGRAM)
        try:
            sock.setsockopt(socket.SOL_SOCKET, socket.SO_RCVBUF, SOCKET_BUF_BYTES)
        except OSError:
            pass
        sock.bind(core.INGEST_SOCK)
        os.chmod(core.INGEST_SOCK, 0o666)
        sock.settimeout(0.5)
        self._sock = sock

    def _process_payload(self, raw_bytes):
        for line in raw_bytes.decode("utf-8", errors="replace").splitlines():
            if not line.strip():
                continue
            try:
                pkt = json.loads(line)
            except json.JSONDecodeError:
                continue

            with self._cfg_lock:
                cfg = self._cfg

            if pkt.get("source") == "remote":
                entry = core.parse_raw_syslog(
                    pkt.get("raw", ""),
                    peer=pkt.get("peer", ""),
                    fallback_ts=pkt.get("ts", ""),
                )
            else:
                epoch, ts_str = core.parse_ts(pkt.get("ts", ""))
                tag = str(pkt.get("tag") or "").strip()
                sev = core.norm_sev(pkt.get("severity"))
                msg = str(pkt.get("msg") or "").strip()
                if tag == "configd.py" and RE_SELF_POLL.search(msg):
                    continue
                if tag in cfg.excluded_programs:
                    continue
                allowed_sevs = core.sev_at_or_above(cfg.min_local_severity)
                if sev not in allowed_sevs:
                    continue
                entry = {
                    "epoch": epoch,
                    "timestamp": ts_str,
                    "host": str(pkt.get("host") or cfg.hostname).strip(),
                    "facility": str(pkt.get("facility") or "syslog").strip(),
                    "severity": sev,
                    "tag": tag,
                    "message": msg,
                }

            if core.should_discard(cfg.rules, entry):
                continue

            entry["severity"] = core.apply_rewrite(cfg.rules, entry)
            try:
                self._ingest_q.put_nowait(entry)
            except queue.Full:
                self._log("warn", "Ingest queue full, dropping log entry")

    def _receiver_loop(self):
        while not self._stop.is_set():
            try:
                data, _ = self._sock.recvfrom(DGRAM_MAX_BYTES)
                if data:
                    self._process_payload(data)
            except socket.timeout:
                continue
            except OSError:
                if not self._stop.is_set():
                    time.sleep(0.1)

    def _writer_loop(self):
        batch = []
        last_flush = time.monotonic()

        while not self._stop.is_set() or not self._ingest_q.empty():
            self._maybe_reload()
            timeout = max(0.05, FLUSH_INTERVAL_SEC - (time.monotonic() - last_flush))
            try:
                item = self._ingest_q.get(timeout=timeout)
                batch.append(item)
            except queue.Empty:
                pass

            due = (time.monotonic() - last_flush) >= FLUSH_INTERVAL_SEC
            if batch and (len(batch) >= FLUSH_BATCH_SIZE or due or self._stop.is_set()):
                try:
                    core.insert_logs(self._conn, batch)
                except Exception as exc:
                    self._log("error", f"SQLite insert failed: {exc}")
                batch.clear()
                last_flush = time.monotonic()

    def _send_digest_if_due(self, conn, cfg, now):
        digest = cfg.rules.get("digest", {})
        if not digest.get("enabled"):
            return

        pending = conn.execute(
            "SELECT * FROM digest_queue ORDER BY id ASC"
        ).fetchall()
        if not pending:
            cooldown_sec = core.parse_dur(digest.get("cooldown", "10m"))
            last_sent_row = conn.execute(
                "SELECT value FROM digest_meta WHERE key = 'last_digest_sent'"
            ).fetchone()
            if last_sent_row and (now - int(last_sent_row["value"])) >= cooldown_sec:
                self._digest_window_sec = 0
            return

        if self._next_digest_flush == 0 or now < self._next_digest_flush:
            return

        # Deduplicate queued triggers by rule_name keeping highest count
        by_rule = {}
        for item in pending:
            rname = item["rule_name"]
            if rname not in by_rule or int(item["count"]) > int(by_rule[rname]["count"]):
                by_rule[rname] = item

        sections = []
        for rname, item in by_rule.items():
            samples = json.loads(item["sample_json"] or "[]")
            above_txt = "+" if item["above"] else ""
            sections.append({
                "heading": f"{rname} ({item['count']} hits)",
                "summary": f"Matched {item['count']} logs at {item['level']}{above_txt} within {item['window_minutes']}m",
                "samples": samples,
            })

        try:
            html = core.build_alert_html(
                f"Logwatch Alert Digest: {len(sections)} rule(s) triggered",
                sections,
                core.ui_footer_url(cfg),
            )
            core.send_email(
                cfg.smtp,
                f"[Logwatch] Alert Digest: {len(sections)} rule(s) triggered",
                html,
            )
            conn.execute("DELETE FROM digest_queue")
            conn.execute(
                "INSERT OR REPLACE INTO digest_meta (key, value) VALUES ('last_digest_sent', ?)",
                (str(now),),
            )
            init_sec = core.parse_dur(digest.get("initial", "5m"))
            max_sec = core.parse_dur(digest.get("max", "2h"))
            mult = float(digest.get("multiplier", 3))
            cur_win = self._digest_window_sec or init_sec
            self._digest_window_sec = min(max_sec, int(cur_win * mult))
            self._next_digest_flush = 0
            conn.execute(
                "INSERT OR REPLACE INTO digest_meta (key, value) VALUES ('window_sec', ?)",
                (str(self._digest_window_sec),),
            )
            conn.commit()
            self._log("info", f"Sent digest email for {len(sections)} rule(s)")
        except Exception as exc:
            self._log("error", f"Digest email failed: {exc}")

    def _run_ticker_once(self, conn):
        with self._cfg_lock:
            cfg = self._cfg

        now = int(time.time())
        try:
            deleted = core.prune_logs(
                conn,
                core.DB_PATH,
                cfg.retention_days,
                cfg.max_db_size_mb,
                now_epoch=now,
            )
            if deleted > 0:
                self._log("info", f"Pruned {deleted} expired/capped log entries")
        except Exception as exc:
            self._log("error", f"Retention prune error: {exc}")

        digest_cfg = cfg.rules.get("digest", {})
        digest_on = bool(digest_cfg.get("enabled", False))
        ignore_rules = cfg.rules.get("ignore", [])

        for rule in cfg.rules.get("alerts", []):
            try:
                cnt, samples = core.eval_alert_rule(conn, rule, ignore_rules, now_epoch=now)
                if cnt == 0:
                    continue

                core.mark_alerted(conn, rule["name"], cnt, now_epoch=now)
                if digest_on:
                    conn.execute(
                        """
                        INSERT INTO digest_queue
                        (rule_name, count, window_minutes, level, above, triggered_at, sample_json)
                        VALUES (?, ?, ?, ?, ?, ?, ?)
                        """,
                        (
                            rule["name"],
                            cnt,
                            rule["window_minutes"],
                            rule["level"],
                            1 if rule.get("above") else 0,
                            now,
                            json.dumps(samples),
                        ),
                    )
                    conn.commit()
                    if self._next_digest_flush == 0:
                        win_sec = self._digest_window_sec or core.parse_dur(digest_cfg.get("initial", "5m"))
                        self._digest_window_sec = win_sec
                        self._next_digest_flush = now + win_sec
                        conn.execute(
                            "INSERT OR REPLACE INTO digest_meta (key, value) VALUES ('next_flush', ?)",
                            (str(self._next_digest_flush),),
                        )
                        conn.commit()
                    continue

                above_txt = " or above" if rule.get("above") else ""
                sections = [{
                    "heading": f"Rule: {rule['name']}",
                    "summary": f"{cnt} matching logs ({rule['level']}{above_txt}) in the last {rule['window_minutes']} minute(s).",
                    "samples": samples,
                }]
                html = core.build_alert_html(
                    f"Logwatch Alert: {rule['name']}",
                    sections,
                    core.ui_footer_url(cfg),
                )
                core.send_email(cfg.smtp, f"[Logwatch] Alert: {rule['name']}", html)
                self._log("info", f"Sent alert email for '{rule['name']}' ({cnt} hits)")
            except Exception as exc:
                self._log("error", f"Alert evaluation error for '{rule.get('name')}': {exc}")

        self._send_digest_if_due(conn, cfg, now)

    def _ticker_loop(self):
        # Dedicated WAL connection avoids cross-thread sqlite3 transaction collisions
        tick_conn = core.open_db(core.DB_PATH)
        try:
            while not self._stop.is_set():
                if self._stop.wait(TICKER_INTERVAL_SEC):
                    break
                self._run_ticker_once(tick_conn)
        finally:
            tick_conn.close()

    def run(self):
        signal.signal(signal.SIGTERM, self._handle_sigterm)
        signal.signal(signal.SIGINT, self._handle_sigterm)
        signal.signal(signal.SIGHUP, self._handle_sighup)

        self._bind_socket()
        self._log("info", f"Listening on {core.INGEST_SOCK} -> {core.DB_PATH}")

        recv_t = threading.Thread(target=self._receiver_loop, daemon=True)
        tick_t = threading.Thread(target=self._ticker_loop, daemon=True)
        recv_t.start()
        tick_t.start()

        try:
            self._writer_loop()
        finally:
            self._stop.set()
            recv_t.join(timeout=2.0)
            tick_t.join(timeout=2.0)
            if self._sock:
                self._sock.close()
            if os.path.exists(core.INGEST_SOCK):
                try:
                    os.unlink(core.INGEST_SOCK)
                except OSError:
                    pass
            self._conn.close()
            self._log("info", "os-logwatch daemon stopped")


if __name__ == "__main__":
    LogwatchDaemon().run()
